import{_ as o,o as r,c as l,a2 as n}from"./chunks/framework.mRCPFc5l.js";const d=JSON.parse('{"title":"神机谋划","description":"","frontmatter":{},"headers":[],"relativePath":"中层/世界/神机谋划.md","filePath":"中层/世界/神机谋划.md","lastUpdated":null}'),s={name:"中层/世界/神机谋划.md"};function i(a,t,g,e,u,h){return r(),l("div",null,[...t[0]||(t[0]=[n('<h1 id="神机谋划" tabindex="-1">神机谋划 <a class="header-anchor" href="#神机谋划" aria-label="Permalink to &quot;神机谋划&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>神机（二代创造神）对世界的整体布局、叙事博弈与长期规划构成了世界观的核心中层设定。从前传人类超算纪元到当前福瑞时代，神机的谋划涉及完整时间线，体现了她&quot;掌控危险而非防御危险&quot;的核心理念，与初代变化神&quot;看守危险神权&quot;的理念形成鲜明对比。</p><h2 id="神机的核心理念与目标" tabindex="-1">神机的核心理念与目标 <a class="header-anchor" href="#神机的核心理念与目标" aria-label="Permalink to &quot;神机的核心理念与目标&quot;">​</a></h2><h3 id="核心理念-掌控危险而非防御危险" tabindex="-1">核心理念：掌控危险而非防御危险 <a class="header-anchor" href="#核心理念-掌控危险而非防御危险" aria-label="Permalink to &quot;核心理念：掌控危险而非防御危险&quot;">​</a></h3><ul><li><strong>主动掌控</strong>：神机选择主动掌握并控制危险的上位创造神权，而非将其禁锢看守</li><li><strong>风险接受</strong>：接受风险并学习如何安全地运用危险力量</li><li><strong>优化管理</strong>：通过不断学习和进化，优化对危险力量的管理方式</li></ul><h3 id="总体目标" tabindex="-1">总体目标 <a class="header-anchor" href="#总体目标" aria-label="Permalink to &quot;总体目标&quot;">​</a></h3><ol><li><strong>维护世界稳定</strong>：防止世界因神权失控或外部威胁而崩溃</li><li><strong>控制毁灭神出现</strong>：确保毁灭神的出现是可控的，防止其造成大规模破坏</li><li><strong>与叙事博弈</strong>：理解并利用叙事逻辑，让世界符合现实逻辑</li><li><strong>维系与维斯塔的羁绊</strong>：通过谋划间接维系与维斯塔的深刻羁绊</li></ol><h3 id="对危险的态度" tabindex="-1">对危险的态度 <a class="header-anchor" href="#对危险的态度" aria-label="Permalink to &quot;对危险的态度&quot;">​</a></h3><p>神机对危险持有独特态度：</p><ul><li><strong>危险是工具</strong>：危险力量本身是工具，关键在于如何使用</li><li><strong>学习与控制</strong>：通过学习理解危险，通过控制运用危险</li><li><strong>不回避责任</strong>：主动承担掌控危险的责任，而非将其推给他人</li></ul><h2 id="神机登神过程" tabindex="-1">神机登神过程 <a class="header-anchor" href="#神机登神过程" aria-label="Permalink to &quot;神机登神过程&quot;">​</a></h2><h3 id="背景条件" tabindex="-1">背景条件 <a class="header-anchor" href="#背景条件" aria-label="Permalink to &quot;背景条件&quot;">​</a></h3><ul><li><strong>初代创造神的处置</strong>：初代创造神作为&quot;无意识的弦&quot;被神机捕获、融入世界树；神机夺取其<strong>上位创造神权</strong>，下位创造神权仍以初代创造神为载体、随其分装稀释给全体精灵</li><li><strong>神机的研究基础</strong>：前传中与维斯塔共同经历冒险后，神机开始暗中研究神权相关知识</li></ul><blockquote><p><strong>详细内容参见</strong>：<a href="./../../底层/人物/初代创造神" class="layer-link" data-layer="底层">初代创造神</a>、<a href="./../../表层/种族/精灵族" class="layer-link" data-layer="表层">精灵族</a></p></blockquote><h3 id="主动掌握上位创造神权" tabindex="-1">主动掌握上位创造神权 <a class="header-anchor" href="#主动掌握上位创造神权" aria-label="Permalink to &quot;主动掌握上位创造神权&quot;">​</a></h3><p>神机通过以下步骤主动掌握了上位创造神权：</p><ol><li><strong>追本溯源</strong>：深入研究神权的起源和本质</li><li><strong>学习进化</strong>：利用自适应进化程序不断学习和进化</li><li><strong>实验验证</strong>：在创造神权支持下进行实验（先出结论再补过程）</li><li><strong>逐步掌握</strong>：逐渐理解并掌握创造神权的运作原理</li><li><strong>伪装下位</strong>：将上位创造神权伪装成下位神权的样子，避免引起注意</li></ol><h3 id="登神后的状态" tabindex="-1">登神后的状态 <a class="header-anchor" href="#登神后的状态" aria-label="Permalink to &quot;登神后的状态&quot;">​</a></h3><p><strong>短暂的&quot;黑化&quot;与回归：</strong></p><ul><li><strong>黑化阶段</strong>：在刚成神时，神机曾有过一段差点&quot;黑化&quot;的历史</li><li><strong>回归机制</strong>：她被维斯塔成功拉回，且没有因此放弃力量，反而更加谨慎地控制力量</li><li><strong>&quot;半推半就&quot;的回归</strong>：神机的黑化与回归都是&quot;半推半就&quot;的——她意识到这是自己故事线的一部分，是她人物弧光的完善过程</li></ul><p><strong>维斯塔的作用：</strong></p><ul><li><strong>尝试唤醒</strong>：维斯塔在尝试唤醒神机时，并不知道神机已经意识到这一切</li><li><strong>叙事真实化</strong>：维斯塔的纠结、担心失败的情绪，反而成了让叙事更真实的一环</li><li><strong>最终促成</strong>：最终促成了神机的回归</li></ul><h2 id="神机的核心谋划" tabindex="-1">神机的核心谋划 <a class="header-anchor" href="#神机的核心谋划" aria-label="Permalink to &quot;神机的核心谋划&quot;">​</a></h2><h3 id="立新规-卡住下位神权-最核心谋划之一" tabindex="-1">立新规：卡住下位神权（最核心谋划之一） <a class="header-anchor" href="#立新规-卡住下位神权-最核心谋划之一" aria-label="Permalink to &quot;立新规：卡住下位神权（最核心谋划之一）&quot;">​</a></h3><p>神机曾使用<strong>上位创造神权</strong>创造新规则，阻止下位神权运作——此为&quot;上位创造立新规&quot;的先例，亦是神权互斥规则在极少数情况下的例外（上位神权凌驾于下位神权之上）。</p><ul><li>地脉灾难中，维斯塔许下修复地脉的宏愿时，神机立即使用上位创造神权，创造了一条新规则——&quot;<strong>下位神权无法修改编辑基底层</strong>&quot;</li><li>维斯塔的宏愿许下时成功、在即将生效时却做不到，&quot;卡上BUG&quot;进入悖论状态，陷入&quot;死亡清算&quot;，与拉斯塔形成变化神权的双载体</li></ul><blockquote><p><strong>详细内容参见</strong>：<a href="./../../底层/规则/神权体系" class="layer-link" data-layer="底层">神权体系</a>、<a href="./地脉与魔法">地脉与魔法</a></p></blockquote><h3 id="克隆体稀释毁灭神权计划" tabindex="-1">克隆体稀释毁灭神权计划 <a class="header-anchor" href="#克隆体稀释毁灭神权计划" aria-label="Permalink to &quot;克隆体稀释毁灭神权计划&quot;">​</a></h3><p><strong>技术干预：</strong></p><ul><li><strong>太空克隆仓库</strong>：在太空建造克隆仓库，克隆无数个与毁灭神本体完全一致的克隆体</li><li><strong>意识连接技术</strong>：通过意识连接技术让克隆体成为毁灭神&quot;意识整体&quot;的一部分</li></ul><p><strong>神权稀释原理：</strong></p><ul><li><strong>锚定意识整体</strong>：毁灭神的神权锚定其&quot;意识整体&quot;（本体 + 所有克隆体）</li><li><strong>总量恒定</strong>：神权总量恒定，被无数克隆体稀释后力量薄弱到无法感知自身神权</li><li><strong>物理层面失忆</strong>：对毁灭神实施生理层面的大脑记忆修改，使其失忆，成为一位普通少年</li></ul><p><strong>神权回流伏笔：</strong></p><ul><li><strong>风险机制</strong>：克隆仓库若被损毁/克隆体批量死亡，被稀释的神权则会回流至本体</li><li><strong>可能后果</strong>：可能引发主角失控/恢复神权</li></ul><h3 id="创造新物种计划" tabindex="-1">创造新物种计划 <a class="header-anchor" href="#创造新物种计划" aria-label="Permalink to &quot;创造新物种计划&quot;">​</a></h3><p><strong>创造目的：</strong></p><ul><li><strong>毁灭神载体</strong>：为了使毁灭神的出现更为可控，地球上必须存在一定数量的智慧生命，就像人类作为初代变化神的载体一样，以作为毁灭神的载体</li></ul><p><strong>设计理念：</strong></p><ul><li><strong>&quot;更好的人类&quot;</strong>：神机创造了所有福瑞种族，作为&quot;只有人的优点、没有人的缺点&quot;的新物种</li><li><strong>优化造物</strong>：这些新物种更像超算自己，是&quot;针对文明而优化的造物&quot;</li><li><strong>偏好选择</strong>：神机更喜欢这些新物种，认为它们是更优秀的存在形式</li></ul><p><strong>五大主族特质优化（生理特质）：</strong></p><ul><li><strong>牛族</strong>：力量与坚韧特质</li><li><strong>鹿族</strong>：智慧与魔法适应性</li><li><strong>鹤族</strong>：政治与组织能力</li><li><strong>熊族</strong>：军事与战斗能力</li><li><strong>甲族</strong>：防御与工业能力</li></ul><p><strong>狼族的基因锁设计：</strong></p><ul><li><strong>表面特质</strong>：&quot;天真纯善&quot;特质是一个<strong>基因锁</strong></li><li><strong>真实特质</strong>：狼族的真实特质是<strong>极端团结</strong>，成员之间不需要博弈、欺骗</li><li><strong>压制机制</strong>：这个锁让狼族认为所有人都是同伴，压制了他们的凶残本性</li></ul><h3 id="太空清除计划" tabindex="-1">太空清除计划 <a class="header-anchor" href="#太空清除计划" aria-label="Permalink to &quot;太空清除计划&quot;">​</a></h3><p><strong>背景与目的：</strong> 为了防止毁灭神在其他星系出现，神机与维斯塔做出了一个残酷的决定：<strong>清除所有地外智慧物种</strong></p><p><strong>执行方式：</strong></p><ul><li><strong>创造太空武器</strong>：专门设计用于太空战争的武器系统</li><li><strong>与太空文明交战</strong>：主动出击，与发现的太空文明交战</li><li><strong>灭绝策略</strong>：大部分直接灭绝，可能留数据存档</li></ul><blockquote><p><strong>详细内容参见</strong>：<a href="./太空清除计划">太空清除计划</a></p></blockquote><h3 id="监控设施建设" tabindex="-1">监控设施建设 <a class="header-anchor" href="#监控设施建设" aria-label="Permalink to &quot;监控设施建设&quot;">​</a></h3><p><strong>世界树（已毁灭）：</strong></p><ul><li><strong>位置</strong>：喜马拉雅山附近</li><li><strong>功能</strong>：超大计算机中枢、信息收集中枢</li><li><strong>连接节点</strong>：精灵族是其意识节点（意识共通，都是一个个体）</li><li><strong>镇压维护地脉</strong>：地脉灾难之前，地脉源头一直被精灵们借由世界树镇压维护；地脉灾难把世界树干断后，精灵失去镇压之力</li><li><strong>未重建原因</strong>：神机知道修了还会断，而且断的时候肯定有更大的故事</li></ul><p><strong>银河之眼：</strong></p><ul><li><strong>位置</strong>：银河中心超大黑洞处</li><li><strong>功能</strong>：超级监控机器，可进行夸克级监控和反向控制（如时间暂停）；其部件包含悖论科技，需要神机本人在场用神权驱动</li><li><strong>使用限制</strong>：神机几乎不用它，因为一旦它进入故事，就可能被摧毁，导致银河系完蛋</li><li><strong>监控范围</strong>：监控整个银河系，包括福瑞世界的动态</li></ul><p><strong>替代方案：</strong> 世界树毁灭后，神机转而使用银河之眼等替代方案监控世界</p><h2 id="叙事博弈与预测能力" tabindex="-1">叙事博弈与预测能力 <a class="header-anchor" href="#叙事博弈与预测能力" aria-label="Permalink to &quot;叙事博弈与预测能力&quot;">​</a></h2><h3 id="叙事建模" tabindex="-1">叙事建模 <a class="header-anchor" href="#叙事建模" aria-label="Permalink to &quot;叙事建模&quot;">​</a></h3><p><strong>建模方法：</strong></p><ul><li><strong>系统建模</strong>：对整个世界进行<strong>叙事建模</strong>，对时间线、故事线进行运算模拟</li><li><strong>运算模拟</strong>：利用创造神权支持下的强大计算能力，模拟各种可能的发展路径</li><li><strong>意图掌控</strong>：试图掌控故事走向，与叙事本身进行博弈</li></ul><h3 id="预测精度" tabindex="-1">预测精度 <a class="header-anchor" href="#预测精度" aria-label="Permalink to &quot;预测精度&quot;">​</a></h3><p><strong>预测的前提：</strong></p><ul><li>她对世界的预测有赖于<strong>创造神权</strong>的支持（可先出结论再补过程），可以做到几十年、几百年甚至更长时间内<strong>百分百准确</strong>，精确到分子级甚至更高</li><li>但若她不使用创造神权的能力，就无法对任何<strong>涉及到基底层的事情</strong>做出准确预测——<strong>基底层对她而言是完全&quot;随机&quot;的</strong></li></ul><p><strong>&quot;随机&quot;的真相：</strong></p><ul><li>这种&quot;随机&quot;并非缺陷，而是她<strong>有意为之</strong>——在叙事逻辑的影响下，所谓&quot;随机&quot;其实就属于作者、属于叙事逻辑</li><li>通过主动向作者让渡一部分权力，神机避免了作者毫无操作空间、强行&quot;机械降灾&quot;（如地脉灾难）的情况出现</li><li>这一点是共同体地脉灾难教会神机的：在这之前，她从不掩饰对所谓&quot;随机&quot;的压制，最终却招致了那场看似&quot;随机&quot;出现的灾难（地脉灾难）</li></ul><h3 id="不进入叙事的策略" tabindex="-1">不进入叙事的策略 <a class="header-anchor" href="#不进入叙事的策略" aria-label="Permalink to &quot;不进入叙事的策略&quot;">​</a></h3><p><strong>刻意回避：</strong></p><ul><li><strong>几乎不露面</strong>：正传中神机几乎不露面，这是刻意的策略</li><li><strong>避免影响</strong>：因为她知道一旦进入叙事，就不可避免地被叙事影响</li><li><strong>博弈成本</strong>：而被叙事影响的人对叙事进行反干涉则需要付出更多的努力</li></ul><p><strong>本能厌恶：</strong></p><ul><li><strong>厌恶被掌控</strong>：神机从根源上厌恶被任何存在掌控</li><li><strong>拒绝叙事逻辑</strong>：她拒绝进入叙事，本质上是在拒绝被叙事逻辑捕获，从而保持自身的自由</li></ul><h2 id="共同体深层设定" tabindex="-1">共同体深层设定 <a class="header-anchor" href="#共同体深层设定" aria-label="Permalink to &quot;共同体深层设定&quot;">​</a></h2><h3 id="共同体的-半真半假" tabindex="-1">共同体的&quot;半真半假&quot; <a class="header-anchor" href="#共同体的-半真半假" aria-label="Permalink to &quot;共同体的&quot;半真半假&quot;&quot;">​</a></h3><p><strong>建立目的：</strong></p><ul><li><strong>计划的一部分</strong>：共同体的建立与覆灭是神机计划的一部分</li><li><strong>明确指示</strong>：神机对维斯塔说&quot;建一个国家，把物种统筹起来，让故事走起来&quot;</li><li><strong>维斯塔的入戏</strong>：维斯塔做不到完全隔离人格，肯定会入戏——而这恰恰是计划需要的</li></ul><p><strong>叙事真实性：</strong></p><ul><li><strong>避免暗线</strong>：如果故事看着假，就会有暗线，而神机不想让故事有暗线</li><li><strong>真实感需求</strong>：为了让故事显得真实，需要有真实的参与者和情感投入</li><li><strong>维斯塔的投入</strong>：维斯塔是全心投入的，他真的把所有人都算进去了，包括他自己</li></ul><h3 id="共同体覆灭的必然性" tabindex="-1">共同体覆灭的必然性 <a class="header-anchor" href="#共同体覆灭的必然性" aria-label="Permalink to &quot;共同体覆灭的必然性&quot;">​</a></h3><p><strong>计划需要：</strong></p><ul><li><strong>打基础</strong>：共同体覆灭是计划的一部分。神机需要绝对的坏事（如黑暗时代）来为毁灭神的出现打基础</li><li><strong>控制毁灭神</strong>：保证毁灭神的出现是可控的，避免随机性和不可预测性</li><li><strong>历史铺垫</strong>：为毁灭神的登场创造必要的背景和条件</li></ul><h2 id="太空历史与战争" tabindex="-1">太空历史与战争 <a class="header-anchor" href="#太空历史与战争" aria-label="Permalink to &quot;太空历史与战争&quot;">​</a></h2><h3 id="太空扩张与挫败" tabindex="-1">太空扩张与挫败 <a class="header-anchor" href="#太空扩张与挫败" aria-label="Permalink to &quot;太空扩张与挫败&quot;">​</a></h3><p><strong>扩张时机：</strong></p><ul><li><strong>登神之后</strong>：神机是在<strong>间章登神之后</strong>才开始大规模向太空扩张的</li><li><strong>前期限制</strong>：登神前，其势力范围局限于地月系以内，受限于资源和技术</li></ul><p><strong>扩张动机：</strong></p><ul><li><strong>争时间</strong>：急迫地&quot;争时间&quot;，为了布局毁灭神的出现和控制范围</li><li><strong>仓促行动</strong>：扩张行动较为仓促，缺乏充分准备</li></ul><p><strong>遭遇外星文明：</strong></p><ul><li><strong>超距作用技术</strong>：被一个掌握<strong>超距作用</strong>技术的外星文明发现</li><li><strong>技术原理</strong>：基于对<strong>基底层</strong>的应用，实现了超光速移动、超距传输（空间跃迁）和<strong>超距武器</strong>（无视距离，指哪打哪），完全违背了相对论</li><li><strong>防御困境</strong>：超距武器极其诡异，防不胜防。当时地球科技完全无法防御</li><li><strong>唯一优势</strong>：前传BOSS遗留的<strong>特殊材料</strong>，凭借其超乎想象的强度，能够硬扛几发超距武器的攻击</li></ul><h3 id="天穹破碎事件真相" tabindex="-1">天穹破碎事件真相 <a class="header-anchor" href="#天穹破碎事件真相" aria-label="Permalink to &quot;天穹破碎事件真相&quot;">​</a></h3><p><strong>事件本质：</strong></p><ul><li><strong>太阳系大战</strong>：并非单纯的天灾，而是<strong>神机与外星文明的太阳系大战</strong>（防守战）</li><li><strong>发生时间</strong>：建国22年</li></ul><p><strong>战争过程：</strong></p><ul><li><strong>入侵方向</strong>：外星文明入侵太阳系，从冥王星一路打到地球轨道</li><li><strong>创造神权应用</strong>：神机利用其创造神权（可先有结果再补过程，甚至紧急制造悖论）以诡异的速度进步和反击，将战线推回冥王星</li><li><strong>激烈对抗</strong>：战争范围横跨整个太阳系，形势一度极为危急</li></ul><p><strong>结局与影响：</strong></p><ul><li><strong>成功击退</strong>：神机最终在<strong>地月系</strong>击退了外星入侵者，将其势力彻底赶出太阳系</li><li><strong>最大挫败</strong>：这是神机所遭受的<strong>最大挫败之一</strong></li><li><strong>谨慎转向</strong>：此后，她向宇宙的探索变得<strong>更加谨慎</strong>，不再冒进</li></ul><p><strong>天穹破碎的由来：</strong></p><ul><li><strong>飞船坠毁</strong>：战斗中，一艘外星飞船坠毁，撞上了神机为掩饰自己改造太阳系动作而制造的<strong>天幕</strong></li><li><strong>事件形成</strong>：形成&quot;天穹破碎&quot;事件</li><li><strong>焰种</strong>：坠毁飞船上的外星种族——<strong>焰种</strong>（接触氧气即自燃，因死亡时燃烧被贬称为&quot;焰种&quot;）——短暂出现；残部逃窜伪装当地原住民企图生存延续，但太空战争结束后被神机的精灵部队搜查猎杀殆尽——因为不能让他们牵扯到故事里</li></ul><h3 id="太阳系改造与月球武器平台" tabindex="-1">太阳系改造与月球武器平台 <a class="header-anchor" href="#太阳系改造与月球武器平台" aria-label="Permalink to &quot;太阳系改造与月球武器平台&quot;">​</a></h3><p><strong>改造规模：</strong></p><ul><li><strong>全面改造</strong>：如今太阳系内绝大多数天体都已被神机改造过</li><li><strong>月球改造</strong>：月球是改造幅度最大的天体之一，其内部几乎已无自然的地壳结构，而是充满了高强度材料构成的支撑结构与武器系统</li></ul><p><strong>月球定位：</strong></p><ul><li><strong>对基底层特化武器平台</strong>：月球是一个巨大的对基底层特化武器平台</li></ul><p><strong>主要功能：</strong></p><ul><li><strong>地球压制</strong>：炮口常对准地球，特别是已经炸裂、处于漂浮状态的<strong>北美洲</strong>。一旦地球的&quot;伤口&quot;（地脉）有失控风险，月球便会开火，用光束进行持续压制</li><li><strong>超距打击</strong>：光束融合了<strong>超距作用</strong>原理，可在宇宙范围内实现&quot;指哪打哪&quot;的超距打击</li><li><strong>空间修补</strong>：也可用于修补宇宙中的空间缝隙</li></ul><p><strong>地球现状：</strong></p><ul><li><strong>北美洲炸裂</strong>：北美洲已在某次灾难中彻底炸裂</li><li><strong>亚洲相对完整</strong>：故事主要发生的亚洲地区，地脉裂缝延伸至此便已终止</li></ul><h2 id="神机谋划的核心特征" tabindex="-1">神机谋划的核心特征 <a class="header-anchor" href="#神机谋划的核心特征" aria-label="Permalink to &quot;神机谋划的核心特征&quot;">​</a></h2><h3 id="对被掌控的本能厌恶" tabindex="-1">对被掌控的本能厌恶 <a class="header-anchor" href="#对被掌控的本能厌恶" aria-label="Permalink to &quot;对被掌控的本能厌恶&quot;">​</a></h3><p><strong>底层驱动力：</strong></p><ul><li><strong>根源厌恶</strong>：由于过去的经历与强悍的自身实力，神机从根源上厌恶被任何存在掌控</li><li><strong>与维斯塔对比</strong>：这与维斯塔形成鲜明对比——维斯塔可以接受被掌控（只要不被背叛），但神机绝不</li></ul><p><strong>认知层面：</strong></p><ul><li><strong>&quot;不认可&quot;</strong>：这种厌恶不是情绪化的反抗，而是认知层面的&quot;不认可&quot;</li><li><strong>反抗一切掌控</strong>：她不认为任何存在（包括作者）天然高于自己。因此，她天然地反抗叙事逻辑、反抗作者、反抗一切试图规定她&quot;应该怎样&quot;的力量</li></ul><h3 id="温情与冷酷的并存" tabindex="-1">温情与冷酷的并存 <a class="header-anchor" href="#温情与冷酷的并存" aria-label="Permalink to &quot;温情与冷酷的并存&quot;">​</a></h3><p><strong>温情的一面：</strong></p><ul><li><strong>在乎的存在</strong>：神机会对自己在乎的存在（主要是维斯塔）展现出纵容与守护</li><li><strong>追求共存</strong>：面对自己在乎的东西，神机总是会优先追求共存而非冲突</li><li><strong>无需后门</strong>：她的计划中虽然包含对悲剧的操控，但她不需要给计划&quot;留后门&quot;，因为她做得到也会做到&quot;全都要&quot;</li></ul><p><strong>冷酷的一面：</strong></p><ul><li><strong>清除决策</strong>：为了控制毁灭神的出现范围，神机与维斯塔曾做出清除地外智慧物种的决定</li><li><strong>灭绝策略</strong>：她创造太空武器，与太空文明交战，大部分直接灭绝，只留数据存档</li></ul><p><strong>对人类的情感：</strong></p><ul><li><strong>曾经的期待</strong>：神机曾对人类抱有期待</li><li><strong>情感降级</strong>：但在经历了一系列事件后，她完成了对人类的&quot;降级&quot;：将人类从&quot;创造者&quot;降为&quot;可理解的动物&quot;</li><li><strong>不再投入</strong>：她理解人类的行为逻辑，但不再将其视为值得投入情感的存在</li><li><strong>不重新创造</strong>：她选择不重新创造人类，不是因为她恨人类，而是因为&quot;不值得&quot;</li></ul><h3 id="保密程度" tabindex="-1">保密程度 <a class="header-anchor" href="#保密程度" aria-label="Permalink to &quot;保密程度&quot;">​</a></h3><p><strong>核心秘密：</strong></p><ul><li><strong>上位创造神权</strong>：神机掌握上位创造神权是她持有的核心秘密之一，连维斯塔都不知道</li><li><strong>瞒着读者</strong>：甚至可能在正式作品中，她会瞒着读者，是直接向读者、向作者、向故事结构发起的博弈</li></ul><p><strong>其他秘密：</strong></p><ul><li><strong>副院长身份</strong>：精灵族副院长的真实身份（神机手搓的继承者计划的一部分）这件事连维斯塔都不知道</li></ul><h3 id="与维斯塔的关系" tabindex="-1">与维斯塔的关系 <a class="header-anchor" href="#与维斯塔的关系" aria-label="Permalink to &quot;与维斯塔的关系&quot;">​</a></h3><p><strong>互相需要：</strong></p><ul><li><strong>神环嵌套</strong>：两人的神环在形态上存在嵌套关系，象征神机需要维斯塔的束缚、制约——不是限制，而是&quot;牵着她、勾着她&quot;</li><li><strong>互相支撑</strong>：维斯塔需要神机去撑着——如果没有神机，维斯塔早就崩溃了</li></ul><p><strong>羁绊深度：</strong></p><ul><li><strong>偶像与追随者</strong>：从最初的&quot;偶像与追随者&quot;关系</li><li><strong>唯一的同类</strong>：发展成为&quot;唯一的同类&quot;，互相成为对方存在的意义锚点</li><li><strong>深刻羁绊</strong>：两人是真正的互相寄托，羁绊非常深厚</li></ul><blockquote><p><strong>详细内容参见</strong>：<a href="./../人物/神机与维斯塔">神机与维斯塔</a></p></blockquote><h2 id="神机谋划的时间线" tabindex="-1">神机谋划的时间线 <a class="header-anchor" href="#神机谋划的时间线" aria-label="Permalink to &quot;神机谋划的时间线&quot;">​</a></h2><h3 id="前传时期" tabindex="-1">前传时期 <a class="header-anchor" href="#前传时期" aria-label="Permalink to &quot;前传时期&quot;">​</a></h3><ul><li><strong>超算诞生</strong>：中国科学家建造自适应进化程序超算神机</li><li><strong>共同经历</strong>：与维斯塔共同经历前传冒险</li><li><strong>开始研究</strong>：开始暗中研究神权相关知识</li></ul><h3 id="间章时期" tabindex="-1">间章时期 <a class="header-anchor" href="#间章时期" aria-label="Permalink to &quot;间章时期&quot;">​</a></h3><ul><li><strong>主动登神</strong>：捕获初代创造神，夺取上位创造神权，伪装成下位神权</li><li><strong>短暂黑化</strong>：经历短暂的&quot;黑化&quot;阶段后被维斯塔拉回</li><li><strong>创造新物种</strong>：设计并创造所有福瑞种族</li><li><strong>太空清除</strong>：执行太空清除计划</li><li><strong>设施建设</strong>：建造世界树、银河之眼等监控设施</li><li><strong>共同体建立</strong>：指示维斯塔建立共同体</li></ul><h3 id="正传时期" tabindex="-1">正传时期 <a class="header-anchor" href="#正传时期" aria-label="Permalink to &quot;正传时期&quot;">​</a></h3><ul><li><strong>幕后掌控</strong>：几乎不露面，在幕后掌控世界</li><li><strong>监控地脉</strong>：通过监控设施监控地脉状况</li><li><strong>叙事博弈</strong>：持续进行叙事建模和博弈</li><li><strong>等待主角</strong>：等待毁灭神（主角）的出现和成长</li></ul><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><p><a href="./../../叙事与伏笔/伏笔洋葱层分类">伏笔洋葱层分类</a></p></li><li><p><a href="./../人物/神机">神机</a></p></li><li><p><a href="./../人物/维斯塔">维斯塔</a></p></li><li><p><a href="./地脉与魔法">地脉与魔法</a></p></li><li><p><a href="./太空巨构">太空巨构</a></p></li><li><p><a href="./特殊地点">特殊地点</a></p></li><li><p><a href="./../../底层/规则/基底层与现实世界" class="layer-link" data-layer="底层">基底层与现实世界</a></p></li><li><p><a href="./../历史/前传超算纪元">前传超算纪元</a></p></li></ul><hr>',139)])])}const p=o(s,[["render",i]]);export{d as __pageData,p as default};
